export function resolveLanguage(preference = "auto", locale = "") {
  if (preference === "ja" || preference === "en") {
    return preference;
  }
  const detected = String(locale || Intl.DateTimeFormat().resolvedOptions().locale)
    .trim()
    .toLowerCase();
  return detected.startsWith("ja") ? "ja" : "en";
}

export function getMessages(language = "en") {
  return messages[language] ?? messages.en;
}

export function getLanguageOptions() {
  return ["auto", "ja", "en"];
}
